def extract_embedded_files(base_dir):
    """Extract all embedded files to the base directory."""
    for rel_path, b64_content in EMBEDDED_FILES.items():
        full_path = os.path.join(base_dir, rel_path)
        os.makedirs(os.path.dirname(full_path), exist_ok=True)
        content = base64.b64decode(b64_content).decode("utf-8")
        # Only write if file does not exist or content changed
        needs_write = True
        if os.path.exists(full_path):
            with open(full_path, "r", encoding="utf-8") as f:
                if f.read() == content:
                    needs_write = False
        if needs_write:
            with open(full_path, "w", encoding="utf-8") as f:
                f.write(content)
    print(f"[SETUP] Extracted {len(EMBEDDED_FILES)} files to {base_dir}")

