db = SQLAlchemy()



# Association table for User-Badge relationship
user_badges = db.Table('user_badges',
    db.Column('user_id', db.Integer, db.ForeignKey('users.id', ondelete='CASCADE'), primary_key=True),
    db.Column('badge_id', db.Integer, db.ForeignKey('badges.id', ondelete='CASCADE'), primary_key=True),
    db.Column('earned_date', db.DateTime, default=datetime.utcnow)
)

class User(db.Model, UserMixin):
    __tablename__ = 'users'
    
    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(100), nullable=False)
    email = db.Column(db.String(120), unique=True, nullable=False)
    password_hash = db.Column(db.String(255), nullable=False)
    role = db.Column(db.String(20), default='student', nullable=False) # 'student' or 'admin'
    registration_date = db.Column(db.DateTime, default=datetime.utcnow)
    
    # Gamification details
    points = db.Column(db.Integer, default=0)
    level = db.Column(db.Integer, default=1)
    
    # Relationships
    attempts = db.relationship('Attempt', backref='user', lazy=True, cascade="all, delete-orphan")
    certificates = db.relationship('Certificate', backref='user', lazy=True, cascade="all, delete-orphan")
    badges = db.relationship('Badge', secondary=user_badges, backref=db.backref('users', lazy='dynamic'))

    def __repr__(self):
        return f'<User {self.email} ({self.role})>'


class Scenario(db.Model):
    __tablename__ = 'scenarios'
    
    id = db.Column(db.Integer, primary_key=True)
    title = db.Column(db.String(150), nullable=False)
    category = db.Column(db.String(50), nullable=False) # 'phishing', 'password', 'social', 'malware', 'incident'
    difficulty = db.Column(db.String(20), nullable=False) # 'easy', 'medium', 'hard'
    description = db.Column(db.Text, nullable=False)
    
    # JSON strings to hold structured configuration for scenarios
    challenge_data = db.Column(db.Text, nullable=False)
    solution_data = db.Column(db.Text, nullable=False)
    
    # Relationships
    attempts = db.relationship('Attempt', backref='scenario', lazy=True, cascade="all, delete-orphan")

    def get_challenge_json(self):
        try:
            return json.loads(self.challenge_data)
        except Exception:
            return {}

    def get_solution_json(self):
        try:
            return json.loads(self.solution_data)
        except Exception:
            return {}

    def __repr__(self):
        return f'<Scenario {self.title} ({self.category})>'


class Attempt(db.Model):
    __tablename__ = 'attempts'
    
    id = db.Column(db.Integer, primary_key=True)
    user_id = db.Column(db.Integer, db.ForeignKey('users.id', ondelete='CASCADE'), nullable=False)
    scenario_id = db.Column(db.Integer, db.ForeignKey('scenarios.id', ondelete='CASCADE'), nullable=False)
    score = db.Column(db.Integer, nullable=False)
    completion_date = db.Column(db.DateTime, default=datetime.utcnow)
    
    answers = db.Column(db.Text, nullable=True) # JSON representation of user submissions
    feedback = db.Column(db.Text, nullable=True) # AI mentor personalized recommendations

    def get_answers_json(self):
        try:
            return json.loads(self.answers) if self.answers else {}
        except Exception:
            return {}

    def __repr__(self):
        return f'<Attempt User:{self.user_id} Scenario:{self.scenario_id} Score:{self.score}>'


class Badge(db.Model):
    __tablename__ = 'badges'
    
    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(100), unique=True, nullable=False)
    description = db.Column(db.String(255), nullable=False)
    icon_class = db.Column(db.String(50), nullable=False) # Bootstrap icon class, e.g. 'bi-shield-lock'
    
    def __repr__(self):
        return f'<Badge {self.name}>'


class Certificate(db.Model):
    __tablename__ = 'certificates'
    
    id = db.Column(db.Integer, primary_key=True)
    user_id = db.Column(db.Integer, db.ForeignKey('users.id', ondelete='CASCADE'), nullable=False)
    certificate_code = db.Column(db.String(100), unique=True, nullable=False)
    issue_date = db.Column(db.DateTime, default=datetime.utcnow)
    score = db.Column(db.Float, nullable=False)

    def __repr__(self):
        return f'<Certificate {self.certificate_code} User:{self.user_id}>'


