class AISecurityMentor:
    @staticmethod
    def get_hint(category, attempt_number=1):
        hints = {
            "phishing": [
                "Look closely at the sender's email domain. Is it an exact match for the official organization, or is it a lookalike domain?",
                "Hover over links to inspect the destination URL. Check if it uses HTTPS, and if the main domain matches the official site.",
                "Notice the tone of the email. Phishing often uses threat-based language (e.g., account suspension) or artificial urgency."
            ],
            "password": [
                "Entropy is a measure of randomness. A long password (passphrase) of 14+ characters is often stronger than a short complex one.",
                "Ensure your password is not in dictionaries. Hackers use massive wordlists of common terms, names, and patterns.",
                "Mixing numbers, uppercase, lowercase, and special symbols expands the character set size, raising the entropy significantly."
            ],
            "social": [
                "Verify the identity of the person via an independent, trusted channel (like calling the internal IT directory number directly).",
                "Be suspicious of anyone requesting you to bypass standard protocols, disable security tools, or share MFA credentials.",
                "Social engineers use urgency, authority (e.g. 'I am from corporate HQ'), and helpfulness to lower your guard."
            ],
            "malware": [
                "Check for suspicious process spawns, like a document or spreadsheet launching cmd.exe or powershell.exe.",
                "Examine registry changes. Registry 'Run' keys are often modified by malware to ensure persistence after reboot.",
                "Look at network logs. A process executing outside standard system paths connecting to an unusual port (like 4444) suggests C2 activity."
            ],
            "incident": [
                "Isolation is the primary key to containing active spread. Disconnect the affected system before backups or forensics.",
                "Do not reboot systems during an active infection unless required; rebooting wipes volatile memory (RAM) where encryption keys may reside.",
                "Identify and patch the vulnerability vector before restoring data and bringing systems back online, otherwise re-infection will occur."
            ]
        }
        
        category_hints = hints.get(category.lower(), ["Always follow the principle of least privilege."])
        index = (attempt_number - 1) % len(category_hints)
        return category_hints[index]

    @staticmethod
    def analyze_phishing_mistakes(missed_indicators, explanations):
        if not missed_indicators:
            return "Fantastic job! You spotted all the phishing indicators in this email."
        
        feedback = "### AI Security Mentor Review\n\nYou missed some key indicators. Let's analyze why they are suspicious:\n\n"
        for ind in missed_indicators:
            expl = explanations.get(ind, "This indicator has anomalies indicating phishing.")
            name = ind.replace("_", " ").title()
            feedback += f"- **{name}**: {expl}\n"
        
        feedback += "\n**Remember**: Phishing attacks exploit trust and urgency. Double-check all external domains and links."
        return feedback

    @staticmethod
    def get_chat_response(query):
        query = query.lower().strip()
        
        # Define predefined keyword responses for the interactive Chat Mentor
        if not query:
            return "Hello! I am your AI Security Mentor. Ask me any cybersecurity questions. For example: 'What is phishing?', 'How do I create a strong password?', or 'What are the steps of Incident Response?'"
        
        if "phishing" in query:
            return (
                "**Phishing** is a social engineering attack where criminals send fraudulent messages designed to trick you "
                "into revealing sensitive information, clicking malicious links, or downloading malware. \n\n"
                "**How to detect phishing:**\n"
                "1. **Sender Address**: Inspect the domain carefully (e.g., `paypal-support.net` instead of `paypal.com`).\n"
                "2. **Hyperlinks**: Hover over links to reveal the true URL before clicking.\n"
                "3. **Urgent Tone**: Look out for phrases demanding immediate action.\n"
                "4. **Generic Greetings**: Phrases like 'Dear Valued Customer' instead of your name.\n"
                "5. **Suspicious Attachments**: Executables masquerading as documents (e.g., `invoice.pdf.exe`)."
            )
            
        elif "password" in query or "entropy" in query or "brute" in query:
            return (
                "**Password Security** depends on three main factors:\n"
                "1. **Length**: Length is the single most important factor. Passwords should be 12-16+ characters.\n"
                "2. **Entropy**: The measure of randomness in a password. Higher entropy makes it mathematically harder to guess.\n"
                "3. **Uniqueness**: Never reuse passwords across accounts. If one site is breached, all your accounts are at risk.\n\n"
                "**What is a Dictionary Attack?**\n"
                "Attackers use automated software to try millions of common words, phrases, and pattern variations (like replacing 'a' with '@'). "
                "A strong password must resist these wordlist checks."
            )
            
        elif "social engineering" in query or "vishing" in query or "impersonation" in query:
            return (
                "**Social Engineering** is the psychological manipulation of people into performing actions or divesting confidential information.\n\n"
                "**Common techniques include:**\n"
                "- **Pretexting**: Creating a fabricated scenario (e.g., 'I am Dave from Corporate IT').\n"
                "- **Phishing/Vishing/Smishing**: Email, phone, or SMS-based manipulation.\n"
                "- **Tailgating**: Following authorized personnel into secure physical zones.\n\n"
                "**Defense**: Always verify identities, never share passwords/MFA codes, and report unauthorized requests immediately."
            )
            
        elif "malware" in query or "virus" in query or "ransomware" in query:
            return (
                "**Malware** (Malicious Software) is any software intentionally designed to cause damage to a computer, server, client, or network.\n\n"
                "**Common Indicators in Sandbox Logs:**\n"
                "- **Unexpected Processes**: E.g., `document.docx` launching `cmd.exe` or `powershell.exe`.\n"
                "- **Persistence Mechanisms**: Modifying registry startup keys (e.g., `HKCU/.../Run`).\n"
                "- **Evasion**: Writing executable binaries in public writable directories (`C:\\Users\\Public\\`).\n"
                "- **Command & Control (C2)**: Outbound TCP connections to unrecognized external IP addresses on suspicious ports (e.g., 4444)."
            )
            
        elif "incident response" in query or "containment" in query or "ir steps" in query:
            return (
                "**Incident Response (IR)** is the structured methodology an organization uses to handle security breaches.\n\n"
                "The industry-standard phases (SANS Framework) are:\n"
                "1. **Preparation**: Training staff and hardening systems.\n"
                "2. **Identification**: Detecting the anomaly or breach.\n"
                "3. **Containment**: Limiting damage. *Immediate network isolation* of infected endpoints is critical.\n"
                "4. **Eradication**: Removing the threat (malware, backdoors) and patching vulnerabilities.\n"
                "5. **Recovery**: Restoring services from clean, secure offline backups.\n"
                "6. **Lessons Learned**: Documenting the event to improve future defenses."
            )
            
        elif "sql injection" in query or "sqli" in query:
            return (
                "**SQL Injection (SQLi)** is a vulnerability where an attacker manipulates SQL queries by injecting malicious SQL statements into input fields.\n\n"
                "**Mitigation:**\n"
                "- Use **Parameterized Queries** (Prepared Statements) - this is how ORMs like SQLAlchemy protect inputs.\n"
                "- Implement strict **Input Validation** and sanitization.\n"
                "- Apply the **Principle of Least Privilege** to database accounts."
            )
            
        elif "xss" in query or "cross-site scripting" in query:
            return (
                "**Cross-Site Scripting (XSS)** occurs when an application includes untrusted data in a web page without proper validation or escaping, "
                "allowing attackers to execute malicious scripts in the victim's browser.\n\n"
                "**Mitigation:**\n"
                "- Use context-aware HTML/Javascript output escaping (Flask's Jinja2 template engine does this automatically by default).\n"
                "- Implement a strong **Content Security Policy (CSP)**.\n"
                "- Mark session cookies as `HttpOnly` to prevent access via Javascript."
            )
            
        else:
            return (
                "That is a great security question. As your AI Security Mentor, I recommend exploring our labs:\n"
                "- Learn how threat actors build deceptive emails in the **Phishing Lab**.\n"
                "- Test how brute-force algorithms crack credentials in the **Password Security Lab**.\n"
                "- Experience real-world crisis management in the **Incident Response Simulator**.\n\n"
                "Could you rephrase your question, or ask about: *phishing*, *passwords*, *social engineering*, *malware*, *incident response*, or *web vulnerabilities*?"
            )


