def generate_certificate_pdf(file_path, student_name, score, certificate_code):
    # Set size to landscape Letter: 792 x 612
    c = canvas.Canvas(file_path, pagesize=landscape(letter))
    width, height = landscape(letter)
    
    # 1. Background Fill (Very light slate navy to feel modern yet printable)
    c.setFillColor(HexColor('#F8F9FA'))
    c.rect(0, 0, width, height, fill=True, stroke=False)
    
    # 2. Outer Border (Dark Navy)
    c.setStrokeColor(HexColor('#0C0F17'))
    c.setLineWidth(4)
    c.rect(20, 20, width - 40, height - 40, fill=False, stroke=True)
    
    # 3. Inner Border (Neon Cyan / Cyber Blue)
    c.setStrokeColor(HexColor('#1A88E9'))
    c.setLineWidth(1.5)
    c.rect(26, 26, width - 52, height - 52, fill=False, stroke=True)
    
    # 4. Corner Decorations (glowing corners representation)
    c.setFillColor(HexColor('#00E5FF'))
    # Top-Left
    c.rect(20, height-30, 10, 10, fill=True, stroke=False)
    # Top-Right
    c.rect(width-30, height-30, 10, 10, fill=True, stroke=False)
    # Bottom-Left
    c.rect(20, 20, 10, 10, fill=True, stroke=False)
    # Bottom-Right
    c.rect(width-30, 20, 10, 10, fill=True, stroke=False)
    
    # 5. Header Title
    c.setFillColor(HexColor('#0C0F17'))
    c.setFont("Helvetica-Bold", 14)
    c.drawCentredString(width / 2.0, height - 80, "CYBERARENA SECURITY ACADEMY")
    
    # Subheader decoration
    c.setStrokeColor(HexColor('#00E5FF'))
    c.setLineWidth(1)
    c.line(width/2.0 - 80, height - 90, width/2.0 + 80, height - 90)
    
    c.setFillColor(HexColor('#6C757D'))
    c.setFont("Helvetica-Bold", 10)
    c.drawCentredString(width / 2.0, height - 105, "INFORMATION SECURITY TRAINING & LAB SIMULATION")
    
    # 6. Main Certificate Title
    c.setFillColor(HexColor('#1A88E9'))
    c.setFont("Helvetica-Bold", 32)
    c.drawCentredString(width / 2.0, height - 170, "CERTIFICATE OF COMPLETION")
    
    # 7. Certificate Body
    c.setFillColor(HexColor('#495057'))
    c.setFont("Helvetica", 14)
    c.drawCentredString(width / 2.0, height - 215, "This is proudly presented to")
    
    # 8. Student Name
    c.setFillColor(HexColor('#0C0F17'))
    c.setFont("Helvetica-Bold", 26)
    c.drawCentredString(width / 2.0, height - 265, student_name.upper())
    
    # Underline student name
    c.setStrokeColor(HexColor('#6C757D'))
    c.setLineWidth(0.5)
    c.line(width/2.0 - 150, height - 275, width/2.0 + 150, height - 275)
    
    # 9. Statement of achievement
    c.setFillColor(HexColor('#495057'))
    c.setFont("Helvetica", 12)
    c.drawCentredString(width / 2.0, height - 315, 
                        "for successfully completing the CyberArena simulation curriculum, proving hands-on proficiency")
    c.drawCentredString(width / 2.0, height - 332, 
                        f"across all core interactive security modules with a cumulative demonstration score of {score}%.")
    
    # 10. Date and Code
    c.setFillColor(HexColor('#6C757D'))
    c.setFont("Helvetica", 10)
    c.drawString(80, 160, f"DATE: {datetime.now().strftime('%B %d, %Y')}")
    c.drawRightString(width - 80, 160, f"VERIFICATION CODE: {certificate_code}")
    
    # 11. Signatures
    # Left Signature: Director
    c.setFont("Helvetica", 10)
    c.setFillColor(HexColor('#0C0F17'))
    # Draw a cursive-like simulated signature
    c.setFont("Courier-BoldOblique", 14)
    c.setFillColor(HexColor('#1A88E9'))
    c.drawString(100, 100, "C. A. Director")
    c.setStrokeColor(HexColor('#6C757D'))
    c.setLineWidth(1)
    c.line(80, 95, 220, 95)
    c.setFont("Helvetica", 9)
    c.setFillColor(HexColor('#6C757D'))
    c.drawString(80, 80, "Director, Cybersecurity Education")
    
    # Right Signature: Security Lead
    c.setFont("Courier-BoldOblique", 14)
    c.setFillColor(HexColor('#1A88E9'))
    c.drawRightString(width - 100, 100, "Security Mentor")
    c.line(width - 220, 95, width - 80, 95)
    c.setFont("Helvetica", 9)
    c.drawRightString(width - 80, 80, "Security Operations Lead")
    
    # 12. Security Seal (Double circles in bottom center)
    seal_x = width / 2.0
    seal_y = 100
    c.setStrokeColor(HexColor('#1A88E9'))
    c.setLineWidth(1)
    c.circle(seal_x, seal_y, 35, fill=False, stroke=True)
    c.setStrokeColor(HexColor('#00E5FF'))
    c.circle(seal_x, seal_y, 31, fill=False, stroke=True)
    
    c.setFillColor(HexColor('#0C0F17'))
    c.setFont("Helvetica-Bold", 6)
    c.drawCentredString(seal_x, seal_y + 8, "CYBERARENA")
    c.drawCentredString(seal_x, seal_y - 2, "VERIFIED")
    c.drawCentredString(seal_x, seal_y - 12, "SECURITY")
    
    c.showPage()
    c.save()


