student_bp = Blueprint('student', __name__, url_prefix='/student')

@student_bp.route('/dashboard')
@login_required
def dashboard():
    if current_user.role == 'admin':
        return redirect(url_for('admin.dashboard'))
        
    # Get user attempts
    attempts = Attempt.query.filter_by(user_id=current_user.id).order_by(Attempt.completion_date.desc()).all()
    
    # Calculate stats
    completed_ids = [a.scenario_id for a in attempts]
    scenarios = Scenario.query.all()
    
    # Separate scenarios by category
    categories = ['phishing', 'password', 'social', 'malware', 'incident']
    cat_stats = {cat: {"total": 0, "completed": 0, "high_score": 0} for cat in categories}
    
    for s in scenarios:
        if s.category in cat_stats:
            cat_stats[s.category]["total"] += 1
            # Find attempts for this scenario
            s_attempts = [a for a in attempts if a.scenario_id == s.id]
            if s_attempts:
                cat_stats[s.category]["completed"] += 1
                cat_stats[s.category]["high_score"] = max(cat_stats[s.category]["high_score"], max(a.score for a in s_attempts))
                
    # Badges progress
    earned_badges = current_user.badges
    all_badges = Badge.query.all()
    
    # Leaderboard
    leaders = User.query.filter_by(role='student').order_by(User.points.desc()).limit(5).all()
    
    # Check if certificate eligible
    cert = Certificate.query.filter_by(user_id=current_user.id).first()
    eligible_for_cert = all(cat_stats[cat]["completed"] > 0 for cat in categories) and not cert

    return render_template(
        'student/dashboard.html',
        attempts=attempts[:5], # Last 5 attempts
        cat_stats=cat_stats,
        earned_badges=earned_badges,
        all_badges=all_badges,
        leaders=leaders,
        cert=cert,
        eligible_for_cert=eligible_for_cert
    )

