@student_bp.route('/scenario/<int:scenario_id>', methods=['GET'])
@login_required
def play_scenario(scenario_id):
    scenario = Scenario.query.get_or_404(scenario_id)
    challenge = scenario.get_challenge_json()
    
    # Route to correct template based on category
    template_map = {
        'phishing': 'student/lab_phishing.html',
        'password': 'student/lab_password.html',
        'social': 'student/lab_social.html',
        'malware': 'student/lab_malware.html',
        'incident': 'student/lab_incident.html'
    }
    
    template = template_map.get(scenario.category, 'student/dashboard.html')
    return render_template(template, scenario=scenario, challenge=challenge)

@student_bp.route('/scenario/<int:scenario_id>/submit', methods=['POST'])
@login_required
def submit_scenario(scenario_id):
    scenario = Scenario.query.get_or_404(scenario_id)
    solution = scenario.get_solution_json()
    challenge = scenario.get_challenge_json()
    
    score = 0
    answers_submitted = {}
    mentor_feedback = ""
    badge_earned = None
    
    category = scenario.category
    
    if category == 'phishing':
        # Retrieve checked elements
        selected_elements = request.form.getlist('indicators')
        required_indicators = solution.get('required_indicators', [])
        
        # Calculate score: Proportional to correct detections and penalties for wrong flags
        correct_flags = 0
        wrong_flags = 0
        
        for el in selected_elements:
            if el in required_indicators:
                correct_flags += 1
            else:
                wrong_flags += 1
                
        # Base score calculation
        if required_indicators:
            base_score = (correct_flags / len(required_indicators)) * 100
            # Deduct 15 points per wrong flag
            score = max(0, int(base_score - (wrong_flags * 15)))
        else:
            score = 100
            
        answers_submitted = {"selected": selected_elements}
        
        # AI Mentor Feedback
        missed = [ind for ind in required_indicators if ind not in selected_elements]
        mentor_feedback = AISecurityMentor.analyze_phishing_mistakes(missed, challenge.get('elements', {}))
        
        if score == 100:
            badge_earned = "Phishing Hunter"
            
    elif category == 'password':
        password = request.form.get('password', '')
        entropy = float(request.form.get('entropy', 0))
        dictionary_match = request.form.get('dictionary_match', 'false') == 'true'
        
        # Validation based on standard metrics
        has_upper = any(c.isupper() for c in password)
        has_lower = any(c.islower() for c in password)
        has_digit = any(c.isdigit() for c in password)
        has_special = any(not c.isalnum() for c in password)
        length = len(password)
        
        score = 0
        if length >= 8: score += 20
        if length >= 12: score += 10
        if has_upper: score += 15
        if has_lower: score += 15
        if has_digit: score += 15
        if has_special: score += 15
        if dictionary_match:
            score = max(10, score - 40) # Heavy penalty for dictionary words
            
        score = min(100, score)
        
        answers_submitted = {"password": password, "entropy": entropy, "dictionary_match": dictionary_match}
        
        # Define response based on score
        tiers = solution.get('feedback_tiers', {})
        if score < 40:
            mentor_feedback = tiers.get('weak', "Weak password.")
        elif score < 75:
            mentor_feedback = tiers.get('medium', "Medium password.")
        elif score < 95:
            mentor_feedback = tiers.get('strong', "Strong password.")
        else:
            mentor_feedback = tiers.get('very_strong', "Very strong password.")
            badge_earned = "Security Defender"
            
    elif category == 'social':
        # Handled in JS via AJAX, or standard form submission
        score = int(request.form.get('score', 0))
        path = request.form.get('path', '')
        badge_name_check = request.form.get('badge', None)
        
        answers_submitted = {"path": path}
        mentor_feedback = "Your decisions resulted in " + ("a complete breach of access credentials." if score == 0 else "safeguarding the network successfully.")
        
        if score == 100 and badge_name_check == "Social Guard":
            badge_earned = "Social Guard"
            
    elif category == 'malware':
        selected_logs = request.form.getlist('malicious_logs')
        malicious_indicators = solution.get('malicious_logs', [])
        
        correct_flags = sum(1 for log in selected_logs if log in malicious_indicators)
        wrong_flags = sum(1 for log in selected_logs if log not in malicious_indicators)
        
        if malicious_indicators:
            base_score = (correct_flags / len(malicious_indicators)) * 100
            score = max(0, int(base_score - (wrong_flags * 15)))
        else:
            score = 100
            
        answers_submitted = {"selected_logs": selected_logs}
        
        # Analyze missed items
        logs_detail = challenge.get('behavioral_logs', [])
        explanations = {log['id']: log['explanation'] for log in logs_detail if log.get('malicious')}
        
        missed = [log for log in malicious_indicators if log not in selected_logs]
        if missed:
            mentor_feedback = "### AI Security Mentor Malware Analysis\n\nYou missed the following critical malware indicators:\n\n"
            for m in missed:
                mentor_feedback += f"- **{m.replace('_', ' ').upper()}**: {explanations.get(m, 'Malicious activity detected.')}\n"
        else:
            mentor_feedback = "Outstanding! You identified every suspicious behavior in the sandbox report."
            badge_earned = "Malware Analyst"
            
    elif category == 'incident':
        score = int(request.form.get('score', 0))
        path = request.form.get('path', '')
        terminal_state = request.form.get('terminal_state', '')
        
        answers_submitted = {"path": path, "state": terminal_state}
        mentor_feedback = f"You completed the incident containment tree. Final outcome: {terminal_state}."
        
        if score == 100:
            badge_earned = "Incident Responder"
            
    # Update Points
    # Earn points equal to score if higher than previous attempt, or just add score for first completions
    prev_attempts = Attempt.query.filter_by(user_id=current_user.id, scenario_id=scenario.id).all()
    prev_high = max([a.score for a in prev_attempts]) if prev_attempts else 0
    
    points_to_add = 0
    if score > prev_high:
        points_to_add = score - prev_high
        current_user.points += points_to_add
        
    # Save Attempt
    new_attempt = Attempt(
        user_id=current_user.id,
        scenario_id=scenario.id,
        score=score,
        answers=json.dumps(answers_submitted),
        feedback=mentor_feedback
    )
    db.session.add(new_attempt)
        
    # Recalculate level: 1 level per 150 points
    new_level = (current_user.points // 150) + 1
    current_user.level = min(5, new_level) # cap at 5
    
    # Earn Badge
    badge_message = ""
    if badge_earned:
        badge_obj = Badge.query.filter_by(name=badge_earned).first()
        if badge_obj and badge_obj not in current_user.badges:
            current_user.badges.append(badge_obj)
            badge_message = f"Congratulations! You earned the '{badge_earned}' badge!"
            
    # Check for Expert Badge (Average of all 5 completed categories >= 80)
    categories = ['phishing', 'password', 'social', 'malware', 'incident']
    completed_cats = []
    cat_scores = []
    
    for cat in categories:
        cat_scenarios = Scenario.query.filter_by(category=cat).all()
        s_ids = [s.id for s in cat_scenarios]
        cat_attempts = Attempt.query.filter_by(user_id=current_user.id).filter(Attempt.scenario_id.in_(s_ids)).all()
        if cat_attempts:
            completed_cats.append(cat)
            cat_scores.append(max([a.score for a in cat_attempts]))
            
    expert_badge = Badge.query.filter_by(name="Cyber Expert").first()
    if len(completed_cats) == 5 and sum(cat_scores)/5.0 >= 80 and expert_badge not in current_user.badges:
        current_user.badges.append(expert_badge)
        badge_message += " You have been awarded the ultimate 'Cyber Expert' badge!"
        
    db.session.commit()
    
    # Check for Certificate generation
    # If student has completed at least 1 lab in all 5 categories, auto-generate certificate
    cert = Certificate.query.filter_by(user_id=current_user.id).first()
    if len(completed_cats) == 5 and not cert:
        cert_code = "CA-" + str(uuid.uuid4())[:8].upper()
        avg_score = sum(cat_scores) / len(cat_scores)
        new_cert = Certificate(
            user_id=current_user.id,
            certificate_code=cert_code,
            score=avg_score
        )
        db.session.add(new_cert)
        db.session.commit()
        badge_message += " You have unlocked your Certificate of Completion!"
        
    flash(f"Lab submitted! Score: {score}/100. {badge_message}", "success" if score >= 70 else "warning")
    return redirect(url_for('student.dashboard'))

@student_bp.route('/analytics')
@login_required
def analytics():
    attempts = Attempt.query.filter_by(user_id=current_user.id).all()
    scenarios = Scenario.query.all()
    
    # Group scores by category
    categories = ['phishing', 'password', 'social', 'malware', 'incident']
    cat_scores = {cat: [] for cat in categories}
    cat_names = {s.id: s.category for s in scenarios}
    
    for a in attempts:
        cat = cat_names.get(a.scenario_id)
        if cat in cat_scores:
            cat_scores[cat].append(a.score)
            
    avg_scores = {}
    for cat in categories:
        scores = cat_scores[cat]
        avg_scores[cat] = int(sum(scores)/len(scores)) if scores else 0
        
    # Weakest/Strongest areas
    non_zero_scores = {k: v for k, v in avg_scores.items() if v > 0}
    strongest = max(non_zero_scores, key=non_zero_scores.get) if non_zero_scores else "None yet"
    weakest = min(non_zero_scores, key=non_zero_scores.get) if non_zero_scores else "None yet"
    
    return render_template('student/analytics.html', avg_scores=avg_scores, strongest=strongest, weakest=weakest)

