@student_bp.route('/certificate/download')
@login_required
def certificate_download():
    cert = Certificate.query.filter_by(user_id=current_user.id).first_or_404()
    
    # Save PDF to a temporary path or send directly
    pdf_filename = f"certificate_{current_user.id}.pdf"
    pdf_dir = os.path.join(os.path.dirname(os.path.dirname(__file__)), 'static', 'certificates')
    
    os.makedirs(pdf_dir, exist_ok=True)
    pdf_path = os.path.join(pdf_dir, pdf_filename)
    
    # Generate the PDF using reportlab
    generate_certificate_pdf(pdf_path, current_user.name, int(cert.score), cert.certificate_code)
    
    return send_file(
        pdf_path,
        mimetype='application/pdf',
        as_attachment=True,
        download_name=f"CyberArena_Certificate_{current_user.name.replace(' ', '_')}.pdf"
    )

