admin_bp = Blueprint('admin', __name__, url_prefix='/admin')

# Decorator to restrict access to Admins only
def admin_required(f):
    @wraps(f)
    def decorated_function(*args, **kwargs):
        if not current_user.is_authenticated or current_user.role != 'admin':
            flash('Access denied. Administrator privileges required.', 'danger')
            return redirect(url_for('auth.login'))
        return f(*args, **kwargs)
    return decorated_function

@admin_bp.route('/dashboard')
@login_required
@admin_required
def dashboard():
    # Metrics
    total_users = User.query.filter_by(role='student').count()
    total_attempts = Attempt.query.count()
    total_certs = Certificate.query.count()
    
    # Calculate average score
    all_attempts = Attempt.query.all()
    avg_score = round(sum(a.score for a in all_attempts) / len(all_attempts), 1) if all_attempts else 0.0
    
    # Category Completion
    scenarios = Scenario.query.all()
    scenario_counts = {cat: 0 for cat in ['phishing', 'password', 'social', 'malware', 'incident']}
    for s in scenarios:
        if s.category in scenario_counts:
            scenario_counts[s.category] += 1
            
    # Recent activity
    recent_attempts = Attempt.query.order_by(Attempt.completion_date.desc()).limit(10).all()
    
    return render_template(
        'admin/dashboard.html',
        total_users=total_users,
        total_attempts=total_attempts,
        total_certs=total_certs,
        avg_score=avg_score,
        recent_attempts=recent_attempts,
        scenario_counts=scenario_counts
    )

