@admin_bp.route('/scenarios/create', methods=['GET', 'POST'])
@login_required
@admin_required
def create_scenario():
    if request.method == 'POST':
        title = request.form.get('title')
        category = request.form.get('category')
        difficulty = request.form.get('difficulty')
        description = request.form.get('description')
        challenge_data = request.form.get('challenge_data')
        solution_data = request.form.get('solution_data')
        
        # Validations
        try:
            # Validate JSON format
            json.loads(challenge_data)
            json.loads(solution_data)
        except ValueError:
            flash("Invalid JSON syntax in challenge or solution data. Please correct it.", "danger")
            return render_template('admin/edit_scenario.html', scenario=None)
            
        new_scenario = Scenario(
            title=title,
            category=category,
            difficulty=difficulty,
            description=description,
            challenge_data=challenge_data,
            solution_data=solution_data
        )
        db.session.add(new_scenario)
        db.session.commit()
        
        flash(f"Scenario '{title}' created successfully.", "success")
        return redirect(url_for('admin.manage_scenarios'))
        
    return render_template('admin/edit_scenario.html', scenario=None)

@admin_bp.route('/scenarios/edit/<int:scenario_id>', methods=['GET', 'POST'])
@login_required
@admin_required
def edit_scenario(scenario_id):
    scenario = Scenario.query.get_or_404(scenario_id)
    
    if request.method == 'POST':
        scenario.title = request.form.get('title')
        scenario.category = request.form.get('category')
        scenario.difficulty = request.form.get('difficulty')
        scenario.description = request.form.get('description')
        
        c_data = request.form.get('challenge_data')
        s_data = request.form.get('solution_data')
        
        try:
            json.loads(c_data)
            json.loads(s_data)
            scenario.challenge_data = c_data
            scenario.solution_data = s_data
        except ValueError:
            flash("Invalid JSON syntax. Changes not saved.", "danger")
            return render_template('admin/edit_scenario.html', scenario=scenario)
            
        db.session.commit()
        flash(f"Scenario '{scenario.title}' updated successfully.", "success")
        return redirect(url_for('admin.manage_scenarios'))
        
    return render_template('admin/edit_scenario.html', scenario=scenario)

