# FLASK APPLICATION FACTORY
# ============================================================

def create_app():
    # Determine base directory (where this script lives)
    BASE_DIR = os.path.dirname(os.path.abspath(__file__))
    APP_DIR = os.path.join(BASE_DIR, "cyberarena_app")
    os.makedirs(APP_DIR, exist_ok=True)

    # Extract embedded template and static files
    extract_embedded_files(APP_DIR)

    # Create Flask app with correct template/static paths
    app = Flask(
        __name__,
        template_folder=os.path.join(APP_DIR, "templates"),
        static_folder=os.path.join(APP_DIR, "static")
    )

    # Configuration
    app.config["SECRET_KEY"] = os.environ.get("SECRET_KEY", "cyberarena_super_secret_key_2026")
    if os.environ.get("TESTING") == "true":
        app.config["TESTING"] = True
        app.config["SQLALCHEMY_DATABASE_URI"] = "sqlite:///:memory:"
        app.config["WTF_CSRF_ENABLED"] = False
    else:
        db_path = os.path.join(APP_DIR, "cyberarena.db")
        app.config["SQLALCHEMY_DATABASE_URI"] = f"sqlite:///{db_path}"
    app.config["SQLALCHEMY_TRACK_MODIFICATIONS"] = False

    # Initialize extensions
    db.init_app(app)

    login_manager = LoginManager()
    login_manager.login_view = "auth.login"
    login_manager.login_message_category = "info"
    login_manager.init_app(app)

    @login_manager.user_loader
    def load_user(user_id):
        return User.query.get(int(user_id))

    # Register blueprints
    app.register_blueprint(auth_bp)
    app.register_blueprint(student_bp)
    app.register_blueprint(admin_bp)

    # Custom template filters
    @app.template_filter("from_json")
    def from_json_filter(value):
        try:
            return json.loads(value)
        except Exception:
            return {}

    @app.template_filter("datetime_format")
    def datetime_format_filter(value, format="%Y-%m-%d %H:%M"):
        if value is None:
            return ""
        return value.strftime(format)

    # Landing page
    @app.route("/")
    def index():
        try:
            user_count = User.query.filter_by(role="student").count()
            scenario_count = Scenario.query.count()
            attempt_count = Attempt.query.count()
        except Exception:
            user_count, scenario_count, attempt_count = 0, 0, 0
        return render_template(
            "landing.html",
            user_count=user_count,
            scenario_count=scenario_count,
            attempt_count=attempt_count
        )

    # Create database tables
    with app.app_context():
        db.create_all()
        # Auto-seed if database is empty and not in testing mode
        if not app.config.get("TESTING") and User.query.count() == 0:
            print("[SETUP] Empty database detected. Seeding initial data...")
            seed_database()

    return app

